declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/catalog_ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$error='';$notice=(string)($_SESSION['dn_materialize_notice']??'');unset($_SESSION['dn_materialize_notice']);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{pv_require_csrf();$sid=(int)($_POST['species_id']??0);$id=dn_materialize($db,$uid,$sid);$d=dn_owned_instance($db,$uid,$id);$_SESSION['dn_materialize_notice']=$d['name'].' materialized at Level 1 with '.$d['abi'].' ABI.';pv_redirect('materialize.php?ready=1');}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Materialization could not be completed.';}
