<div class="pv-game-layout"><?php pv_game_side_menu('materialize.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">DIGILAB // RECONSTRUCTION</span><h1>Scan & Materialize</h1><p class="pv-subtle">Recover scan data by defeating wild Digimon. Materialize at 100% or higher: conversion uses all accumulated data and creates a level 1 Digimon. Every extra 20% grants 1 starting ABI, up to 5 ABI at 200%.</p></div><a class="pv-button" href="<?=pv_h(pv_url('map_select.php'))?>">Find signatures</a></div>
