<?php dn_catalog_filters($list);dn_catalog_pager($list,'materialize.php');?><div class="dn-scan-grid">
<?php foreach($list['rows'] as $s):$scan=(int)$s['scan_percent'];$seen=(int)$s['first_seen']>0||(int)$s['owned']>0;?><article class="dn-scan-card <?=$seen?'':'is-locked'?>"><img loading="lazy" src="<?=pv_h(pv_static($s['sprite']))?>" alt="<?=$seen?pv_h($s['name']):'Unknown Digimon'?>"><small><?=pv_h($s['stage'].' · '.$s['attribute'].(dn_is_paradox($s)?' · PARADOX':''))?></small><h3><?=$seen?pv_h($s['name']):'UNKNOWN SIGNATURE'?></h3><div class="dn-scan-meter"><i style="width:<?=min(100,(int)round($scan/2))?>%"></i></div><div class="dn-scan-meta"><span><?=$scan?> / 200% DATA</span><span><?=(int)$s['owned']?> OWNED</span></div>
<?php if($scan>=100):?><form method="post"><?=pv_csrf_field()?><input type="hidden" name="species_id" value="<?=(int)$s['id']?>"><button class="pv-button">Materialize · <?=$scan?>% → <?=dn_conversion_abi($scan)?> ABI</button></form><?php else:?><p class="pv-subtle"><?=100-$scan?>% more to materialize.</p><?php endif;?></article><?php endforeach;?></div>
<?php if(!$list['rows']):?><div class="pv-empty">No signatures match these filters.</div><?php endif;?><?php dn_catalog_pager($list,'materialize.php');?></section></main></div><?php pv_page_end();?>
